table credit_transactions: CREATE TABLE `credit_transactions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `customerId` INTEGER NOT NULL, `amount` REAL NOT NULL, `type` TEXT NOT NULL, `saleId` INTEGER, `notes` TEXT NOT NULL, `balanceAfter` REAL NOT NULL, `createdAt` INTEGER NOT NULL, FOREIGN KEY(`customerId`) REFERENCES `customers`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE)
table customers: CREATE TABLE `customers` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `phone` TEXT NOT NULL, `email` TEXT NOT NULL, `creditBalance` REAL NOT NULL DEFAULT 0.0, `totalPurchases` REAL NOT NULL DEFAULT 0.0, `visitCount` INTEGER NOT NULL DEFAULT 0, `notes` TEXT NOT NULL, `createdAt` INTEGER NOT NULL)
table expenses: CREATE TABLE `expenses` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `amount` REAL NOT NULL, `category` TEXT NOT NULL, `supplierName` TEXT NOT NULL, `notes` TEXT NOT NULL, `receiptRef` TEXT NOT NULL, `paidFromDrawer` INTEGER NOT NULL DEFAULT 0, `cashierId` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL)
table ledger_entries: CREATE TABLE `ledger_entries` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `at` INTEGER NOT NULL, `kind` TEXT NOT NULL, `saleId` INTEGER NOT NULL, `receipt` TEXT NOT NULL, `cents` INTEGER NOT NULL, `cashCents` INTEGER NOT NULL, `method` TEXT NOT NULL)
table mpesa_payments: CREATE TABLE `mpesa_payments` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `code` TEXT NOT NULL, `amount` REAL NOT NULL, `senderName` TEXT NOT NULL, `senderPhone` TEXT NOT NULL, `receivedAt` INTEGER NOT NULL, `rawMessage` TEXT NOT NULL, `createdAt` INTEGER NOT NULL)
table products: CREATE TABLE `products` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `barcode` TEXT NOT NULL, `sku` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `price` REAL NOT NULL, `costPrice` REAL NOT NULL, `stock` INTEGER NOT NULL, `lowStockThreshold` INTEGER NOT NULL, `category` TEXT NOT NULL, `unit` TEXT NOT NULL, `imageUri` TEXT, `taxRate` REAL NOT NULL, `supplierName` TEXT NOT NULL DEFAULT '', `supplierPhone` TEXT NOT NULL DEFAULT '', `reorderQuantity` INTEGER NOT NULL DEFAULT 0, `batchNumber` TEXT NOT NULL DEFAULT '', `expiryDate` INTEGER NOT NULL DEFAULT 0, `pluCode` TEXT NOT NULL DEFAULT '', `isWeighed` INTEGER NOT NULL DEFAULT 0, `pricePerKg` REAL NOT NULL DEFAULT 0.0, `stockKg` REAL NOT NULL DEFAULT 0.0, `isActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL)
table purchase_order_items: CREATE TABLE `purchase_order_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `poId` INTEGER NOT NULL, `productId` INTEGER NOT NULL, `productName` TEXT NOT NULL, `quantity` REAL NOT NULL, `receivedQty` REAL NOT NULL, `unitCost` REAL NOT NULL)
table purchase_orders: CREATE TABLE `purchase_orders` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `supplierId` INTEGER NOT NULL, `status` TEXT NOT NULL, `notes` TEXT NOT NULL, `amountPaid` REAL NOT NULL, `createdAt` INTEGER NOT NULL, `orderedAt` INTEGER NOT NULL, `receivedAt` INTEGER NOT NULL)
table sale_item_costs: CREATE TABLE `sale_item_costs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `saleItemId` INTEGER NOT NULL, `batchId` INTEGER NOT NULL, `quantity` REAL NOT NULL, `unitCost` REAL NOT NULL)
table sale_items: CREATE TABLE `sale_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `saleId` INTEGER NOT NULL, `productId` INTEGER NOT NULL, `productBarcode` TEXT NOT NULL, `productName` TEXT NOT NULL, `unitPrice` REAL NOT NULL, `quantity` INTEGER NOT NULL, `discountAmount` REAL NOT NULL, `taxAmount` REAL NOT NULL, `lineTotal` REAL NOT NULL, `weightKg` REAL NOT NULL DEFAULT 0.0, `costTotal` REAL NOT NULL DEFAULT 0.0, `stockApplied` INTEGER NOT NULL DEFAULT -1, FOREIGN KEY(`saleId`) REFERENCES `sales`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`productId`) REFERENCES `products`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT)
table sales: CREATE TABLE `sales` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `receiptNumber` TEXT NOT NULL, `subtotal` REAL NOT NULL, `taxAmount` REAL NOT NULL, `discountAmount` REAL NOT NULL, `totalAmount` REAL NOT NULL, `amountPaid` REAL NOT NULL, `changeGiven` REAL NOT NULL, `cashPortion` REAL NOT NULL DEFAULT 0.0, `paymentMethod` TEXT NOT NULL, `mpesaRef` TEXT, `status` TEXT NOT NULL, `cashierId` INTEGER NOT NULL, `notes` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `statusChangedAt` INTEGER NOT NULL DEFAULT 0, `totalCents` INTEGER NOT NULL DEFAULT 0, `cashPortionCents` INTEGER NOT NULL DEFAULT 0)
table shifts: CREATE TABLE `shifts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `cashierId` INTEGER NOT NULL, `cashierName` TEXT NOT NULL, `clockIn` INTEGER NOT NULL, `clockOut` INTEGER, `openingFloat` REAL NOT NULL, `closingFloat` REAL, `totalCashSales` REAL NOT NULL, `totalMpesaSales` REAL NOT NULL, `totalCardSales` REAL NOT NULL, `totalSales` REAL NOT NULL, `totalTransactions` INTEGER NOT NULL, `totalDiscounts` REAL NOT NULL, `totalItemsSold` INTEGER NOT NULL, `expectedCash` REAL NOT NULL, `cashDiscrepancy` REAL NOT NULL, `cashPaidOut` REAL NOT NULL DEFAULT 0.0, `cashRefunded` REAL NOT NULL DEFAULT 0.0, `notes` TEXT NOT NULL, `status` TEXT NOT NULL, FOREIGN KEY(`cashierId`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE)
table stock_batches: CREATE TABLE `stock_batches` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `productId` INTEGER NOT NULL, `receivedAt` INTEGER NOT NULL, `quantity` REAL NOT NULL, `remaining` REAL NOT NULL, `unitCost` REAL NOT NULL, `source` TEXT NOT NULL, `batchNumber` TEXT NOT NULL, `expiryDate` INTEGER NOT NULL)
table suppliers: CREATE TABLE `suppliers` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `phone` TEXT NOT NULL, `email` TEXT NOT NULL, `address` TEXT NOT NULL, `notes` TEXT NOT NULL, `isActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL)
table sync_log: CREATE TABLE `sync_log` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `entityType` TEXT NOT NULL, `entityId` INTEGER NOT NULL, `operation` TEXT NOT NULL, `deviceId` TEXT NOT NULL, `payload` TEXT NOT NULL, `status` TEXT NOT NULL, `createdAt` INTEGER NOT NULL)
table users: CREATE TABLE `users` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `username` TEXT NOT NULL, `pinHash` TEXT NOT NULL, `displayName` TEXT NOT NULL, `role` TEXT NOT NULL, `isActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL)
